def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0]); key={}
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0,8): key.setdefault(grid[r][c],[]).append((r,c))
    def ctr(v):
        p=key[v]; return (sum(r for r,c in p)/len(p),sum(c for r,c in p)/len(p))
    # In the key the three colors form a T: upper color maps to upper-left,
    # left color maps to lower-left, right/lower color maps to right arm.
    vals=list(key)
    upper=min(vals,key=lambda v:ctr(v)[0])
    left=min(vals,key=lambda v:ctr(v)[1])
    right=next(v for v in vals if v not in (upper,left))
    # The template comprises 4x4 upper-left, 4x8 upper-right arm and 4x8 lower-left.
    for r in range(h):
      for c in range(w):
        if grid[r][c]==8:
          if r<7: out[r][c]=upper
          elif r<11: out[r][c]=right
          else: out[r][c]=left
    return out
